# Abfragen fuer den Struktur-Export (schema.sql) der ImmoBase-Datenbank.
# Jede Abfrage liefert eine Spalte "s" mit fertigen SQL-Anweisungen.
QUERIES = [
 ("Erweiterungen", """select format('create extension if not exists %I;', extname) s from pg_extension where extname not in ('plpgsql') order by 1"""),
 ("Sequenzen", """select format('create sequence if not exists public.%I;', sequencename) s from pg_sequences where schemaname='public' order by 1"""),
 ("Tabellen", """select format('create table if not exists public.%I (%s%s);', c.relname,
   string_agg(format('%I %s%s%s%s', a.attname, format_type(a.atttypid,a.atttypmod),
     case when a.attidentity='a' then ' generated always as identity' when a.attidentity='d' then ' generated by default as identity' else '' end,
     case when d.adbin is not null and a.attidentity='' then ' default '||pg_get_expr(d.adbin,d.adrelid) else '' end,
     case when a.attnotnull then ' not null' else '' end), ', ' order by a.attnum),
   coalesce((select ', primary key ('||string_agg(quote_ident(a2.attname), ',' order by a2.attnum)||')' from pg_index i join pg_attribute a2 on a2.attrelid=i.indrelid and a2.attnum = any(i.indkey) where i.indrelid=c.oid and i.indisprimary),'')) s
 from pg_class c join pg_namespace n on n.oid=c.relnamespace join pg_attribute a on a.attrelid=c.oid and a.attnum>0 and not a.attisdropped
 left join pg_attrdef d on d.adrelid=c.oid and d.adnum=a.attnum
 where n.nspname='public' and c.relkind='r' group by c.oid, c.relname order by c.relname"""),
 ("Constraints", """select format('alter table %s add constraint %I %s;', conrelid::regclass, conname, pg_get_constraintdef(oid)) s from pg_constraint where connamespace='public'::regnamespace and contype in ('u','c','f') order by contype desc, 1"""),
 ("Indizes", """select indexdef||';' s from pg_indexes i where schemaname='public' and not exists (select 1 from pg_constraint c where c.conindid=(quote_ident(i.schemaname)||'.'||quote_ident(i.indexname))::regclass) order by 1"""),
 ("Funktionen", """select pg_get_functiondef(p.oid)||';' s from pg_proc p where p.pronamespace='public'::regnamespace and p.prokind in ('f','p') and not exists (select 1 from pg_depend d where d.objid=p.oid and d.deptype='e') order by p.proname"""),
 ("Views", """select format('create or replace view public.%I as %s', viewname, definition) s from pg_views where schemaname='public' order by 1"""),
 ("Trigger", """select pg_get_triggerdef(t.oid)||';' s from pg_trigger t join pg_class c on c.oid=t.tgrelid join pg_namespace n on n.oid=c.relnamespace where not t.tgisinternal and n.nspname in ('public','auth','storage') and not exists (select 1 from pg_depend d where d.objid=t.oid and d.deptype='e') order by 1"""),
 ("RLS", """select format('alter table %I.%I enable row level security;', n.nspname, c.relname) s from pg_class c join pg_namespace n on n.oid=c.relnamespace where n.nspname='public' and c.relkind='r' and c.relrowsecurity order by 1"""),
 ("Policies", """select format('create policy %I on %I.%I as %s for %s to %s%s%s;', policyname, schemaname, tablename, permissive, cmd, array_to_string(roles, ', '),
   case when qual is not null then ' using ('||qual||')' else '' end, case when with_check is not null then ' with check ('||with_check||')' else '' end) s
 from pg_policies where schemaname in ('public','storage') order by schemaname, tablename, policyname"""),
 ("Rechte Tabellen", """select s from (select 'revoke all on all tables in schema public from anon, authenticated;' s, 0 o union all
   select format('grant %s on public.%I to %I;', string_agg(privilege_type, ', '), table_name, grantee), 1 from information_schema.role_table_grants where table_schema='public' and grantee in ('anon','authenticated') group by table_name, grantee
   union all
   select format('grant %s (%s) on public.%I to %I;', privilege_type, string_agg(quote_ident(column_name), ', ' order by column_name), table_name, grantee), 2 from information_schema.column_privileges cp
     where table_schema='public' and grantee in ('anon','authenticated')
       and not exists (select 1 from information_schema.role_table_grants g where g.table_schema='public' and g.table_name=cp.table_name and g.grantee=cp.grantee and g.privilege_type=cp.privilege_type)
     group by privilege_type, table_name, grantee) x order by o, s"""),
 ("Rechte Funktionen", """select s from (select 'revoke execute on all functions in schema public from public, anon, authenticated;' s, 0 o union all
   select format('grant execute on function %s to %I;', p.oid::regprocedure, r.rolname), 1 from pg_proc p cross join (values ('anon'),('authenticated')) r(rolname)
   where p.pronamespace='public'::regnamespace and has_function_privilege(r.rolname, p.oid, 'execute')) x order by o, s"""),
 ("Speicher-Buckets", """select format('insert into storage.buckets (id, name, public, file_size_limit, allowed_mime_types) values (%L, %L, %s, %s, %L) on conflict (id) do update set public = excluded.public;', id, name, public, coalesce(file_size_limit::text,'null'), allowed_mime_types) s from storage.buckets order by id"""),
 ("Geplante Jobs (pg_cron)", """select format('select cron.schedule(%L, %L, %L);', jobname, schedule, command) s from cron.job order by jobname"""),
]
